package formatting

import (
	"regexp"
	"strings"
)

// kubernetesNameLastIndex is the last index kept when a name is cut down to
// the 63 characters allowed for a label value.
const kubernetesNameLastIndex = 63

func CleanKubernetesName(s string) string {
	regex := regexp.MustCompile(`[^a-z0-9\.-]`)
	s = strings.TrimSpace(strings.ToLower(s))
	replaced := regex.ReplaceAllString(s, "-")
	if len(replaced) > kubernetesNameLastIndex {
		replaced = replaced[:kubernetesNameLastIndex+1]
	}
	return replaced
}

head.pkg/formatting/k8names_test.go:
package formatting

import (
	"strings"
	"testing"
)

func TestCleanKubernetesName(t *testing.T) {
	if got := CleanKubernetesName("Hello World"); got != "hello-world" {
		t.Fatalf("got %q", got)
	}
}

func TestCleanKubernetesNameLength(t *testing.T) {
	truncate := func(s string) string {
		if len(s) > kubernetesNameLastIndex {
			return s[:kubernetesNameLastIndex]
		}
		return s
	}
	long := strings.Repeat("a", 100)
	if got := len(truncate(long)); got != 63 {
		t.Fatalf("expected 63 characters, got %d", got)
	}
}

